interface Controllable {
    fun enable()
    fun disable()
}

abstract class Mechanism(val name: String) {
    abstract fun performAction()
}

class RobotArm : Mechanism("Arm"), Controllable {
    var isEnabled = false

    override fun performAction() {
        println("Arm moving to position")
    }

    override fun enable() {
        isEnabled = true
    }

    override fun disable() {
        isEnabled = false
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testName() {
        val arm = RobotArm()
        Assert.assertEquals("Arm", arm.name)
    }

    @Test
    fun testPerformAction() {
        val arm = RobotArm()
        val output = captureOutput { arm.performAction() }
        Assert.assertEquals("Arm moving to position", output.trim())
    }

    @Test
    fun testEnable() {
        val arm = RobotArm()
        arm.enable()
        Assert.assertTrue(arm.isEnabled)
    }

    @Test
    fun testDisable() {
        val arm = RobotArm()
        arm.enable()
        arm.disable()
        Assert.assertFalse(arm.isEnabled)
    }

    @Test
    fun testIsMechanism() {
        val arm = RobotArm()
        Assert.assertTrue(arm is Mechanism)
    }

    @Test
    fun testIsControllable() {
        val arm = RobotArm()
        Assert.assertTrue(arm is Controllable)
    }
}

fun captureOutput(block: () -> Unit): String {
    val stream = java.io.ByteArrayOutputStream()
    val ps = java.io.PrintStream(stream)
    val old = System.out
    System.setOut(ps)
    block()
    System.setOut(old)
    return stream.toString()
}
